declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Theme\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\Document\Theme\Application\Usecase\Create\ThemeCreateUsecase;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeUidVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeNameVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeIsDefaultVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeEnabledVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\Theme\Application\Usecase\Create\ThemeCreateParams;
use Civi\Lughauth\Features\Document\Theme\Application\Usecase\Create\ThemeCreateResult;

class ThemeCreateController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SqlTemplate $sql,
        private readonly ThemeCreateUsecase $createUsecase,
    ) {
    }
    #[OA\Post(
        path: "/api/document/theme",
        tags: ["Theme"],
        description:"Create",
        requestBody: new OA\RequestBody(content: new OA\JsonContent(type: "object", ref:"#/components/schemas/ThemeApiDTO")),
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/ThemeApiDTO")),
              new OA\Response(response: 422, description: "Constraint error"),
          ]
    )]
    public function create(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Create Theme");
        $span = $this->startSpan("Create Theme");
        $this->sql->begin();
        try {
            $value = $this->readTheme($request);
            $result = $this->createUsecase->create($value);
            $this->sql->commit();
            $value = $this->mapTheme($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(201)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }

    private function readTheme(ServerRequestInterface $request): ThemeCreateParams
    {
        $this->logDebug("Read entity for Theme");
        $span = $this->startSpan("Read entity for Theme");
        try {
            $parsed = $request->getParsedBody() ?? [];
            $body = is_array($parsed) ? $parsed : get_object_vars($parsed);
            $errorsList = new ConstraintFailList();
            $value = new ThemeCreateParams();
            $valueUid = ThemeUidVO::tryFrom($body['uid'] ?? null, $errorsList);
            if (null !== $valueUid) {
                $value->uid($valueUid);
            }
            if (in_array('tenant', array_keys($body))) {
                $value->tenant(ThemeTenantVO::tryFrom(isset($body['tenant']['$ref']) ? new TenantRef($body['tenant']['$ref']) : null, $errorsList));
            }
            $valueName = ThemeNameVO::tryFrom($body['name'] ?? null, $errorsList);
            if (null !== $valueName) {
                $value->name($valueName);
            }
            $value->isDefault(ThemeIsDefaultVO::tryFrom($body['isDefault'] ?? null, $errorsList));
            $value->enabled(ThemeEnabledVO::tryFrom($body['enabled'] ?? null, $errorsList));
            $value->version(ThemeVersionVO::tryFrom($body['version'] ?? null, $errorsList));
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            return $value;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function mapTheme(ServerRequestInterface $request, ThemeCreateResult $value): ThemeApiDTO
    {
        $this->logDebug("Map entity to output dto for Theme");
        $span = $this->startSpan("Map entity to output dto for Theme");
        try {
            $tenant = $value->getTenant();
            $dto = new ThemeApiDTO();
            $dto->uid = $value->getUid();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->name = $value->getName();
            $dto->isDefault = $value->isIsDefault();
            $dto->enabled = $value->isEnabled();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
